// Steam Deck UI sounds bundled as base64 data URIs so playback has zero runtime
// dependencies (no Steam internals, no asset serving). Sources committed in
// assets/sounds/; regenerate with scripts if the wavs change.
// deck_ui_misc_08.wav (join), deck_ui_misc_01.wav (leave),
// deck_ui_out_of_game_detail.wav (exit menu), deck_ui_launch_game.wav (launch).

export const joinSoundUri =
  "data:audio/wav;base64,";

export const leaveSoundUri =
  "data:audio/wav;base64,";

// deck_ui_out_of_game_detail.wav — leaving the co-op lobby page.
export const exitMenuSoundUri =
  "data:audio/wav;base64,";

// deck_ui_launch_game.wav — Start pressed, game launch beginning.
export const launchGameSoundUri =
  "data:audio/wav;base64,";
